from collections import defaultdict, deque
import random

def shortest_path(adj, n, s, t):
    if s == t:
        return 0
    dist = [-1] * n
    dist[s] = 0
    queue = deque([s])
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                if v == t:
                    return dist[v]
                queue.append(v)
    return float('inf')

def can_add_edge(adj, n, u, v, min_girth=7):
    if v in adj[u]:
        return False
    d = shortest_path(adj, n, u, v)
    return d >= min_girth - 1

def greedy_build_graph(n=30, min_edges=33, min_girth=7, seed=42):
    random.seed(seed)
    adj = defaultdict(set)
    edges = []
    pairs = [(i,j) for i in range(n) for j in range(i+1, n)]
    random.shuffle(pairs)
    for u, v in pairs:
        if can_add_edge(adj, n, u, v, min_girth):
            adj[u].add(v)
            adj[v].add(u)
            edges.append((u,v))
            if len(edges) >= min_edges:
                break
    return edges, adj

def compute_girth(adj, n):
    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        parent = [-1] * n
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
        if min_cycle <= 6:
            return min_cycle
    return min_cycle

def is_3colorable(adj, n):
    color = [-1] * n
    def get_available(v):
        used = set(color[u] for u in adj[v] if color[u] != -1)
        return [c for c in range(3) if c not in used]
    def backtrack(v):
        if v == n:
            return True
        for c in get_available(v):
            color[v] = c
            if backtrack(v + 1):
                return True
            color[v] = -1
        return False
    if backtrack(0):
        return True, color[:]
    return False, None

# Build the graph
edges, adj = greedy_build_graph(30, 33, 7, 0)
print(f"Edges: {len(edges)}")

# Verify girth
g = compute_girth(adj, 30)
print(f"Girth: {g}")

# Check 3-colorability
colorable, coloring = is_3colorable(adj, 30)
print(f"3-colorable: {colorable}")

if colorable:
    # Verify
    valid = all(coloring[u] != coloring[v] for u, v in edges)
    print(f"Coloring valid: {valid}")
    print(f"Coloring: {coloring}")

print(f"\nEdge list:")
for e in sorted(edges):
    print(e)
